'use strict';
const $ = (q,root=document)=>root.querySelector(q);
const $$ = (q,root=document)=>[...root.querySelectorAll(q)];
const iconPaths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',agents:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 9v-3a6 6 0 0 0-3-5"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3 2.5c-.5.2-.5 1-.5 2M12 17h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6L16 3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h10V3M7 21v-7h10v7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5"/>',funnel:'<path d="M3 4h18l-7 8v7l-4 2v-9L3 4Z"/>',file:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8M8 16h5"/>',external:'<path d="M14 3h7v7M10 14 21 3M10 3H3v18h18v-7"/>',circle:'<circle cx="12" cy="12" r="7"/>',loading:'<path d="M12 3a9 9 0 1 1-9 9"/>'};
function ico(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[n]||iconPaths.spark}</svg>`;}
function paintIcons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=ico(el.dataset.icon));}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('sr-Latn-RS',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const number=n=>new Intl.NumberFormat('sr-Latn-RS',{maximumFractionDigits:1}).format(n);
const PHASES=[
 {name:'Product Market Fit',short:'Product Market Fit',input:100,output:50,duration:'2–4 sata',demo:18000,desc:'Od vaših prednosti do 100 poslovnih ideja. Agenti procenjuju svaki biznis plan i biraju 50 sa najvećim potencijalom.',tasks:['Generisanje 100 ideja za izabranu industriju','Izrada biznis planova, finansija, RACI i rokova','Nezavisna evaluacija 24 stručna agenta','Rangiranje i izbor 50 najboljih ideja'],hint:'Prvo kvalitet, pa obim.',hintText:'Svaka ideja dobija zaseban biznis plan: tržište, problem, rešenje, tehnologiju, odgovornosti, rokove, finansije i očekivani ROI.'},
 {name:'Go-To-Market',short:'Go-To-Market',input:50,output:30,duration:'1–2 dana',demo:20000,desc:'Definišite kome prodajete, u kom regionu i po kojoj ceni. Od 50 strategija agenti biraju 30 za testiranje tržišta.',tasks:['Određivanje regiona i idealnog profila kupca (ICP)','Procena broja kupaca i dostupnih kanala','Formiranje cena i kataloga proizvoda','Evaluacija strategija i izbor 30 ideja'],hint:'Pravi proizvod. Pravi kupac.',hintText:'Za svaku ideju pripremaju se region, profil kupca, veličina publike, cena, katalog i kombinacija sajta, emaila i društvenih mreža.'},
 {name:'Marketing',short:'Marketing',input:30,output:15,duration:'2–8 nedelja',demo:24000,desc:'Testirajte 30 ideja uz jednak marketinški budžet. Metrike kupaca i ocene agenata odlučuju kojih 15 ide dalje.',tasks:['Priprema sajtova, kampanja i email sekvenci','Raspodela jednakog budžeta za svih 30 ideja','Praćenje poseta, email odgovora i pretplata','Poređenje metrika i izbor 15 najboljih ideja'],hint:'Jednaki uslovi za svaku ideju.',hintText:'Svih 30 ideja dobija isti test budžet. U demo modelu ukupan budžet za ovu fazu je 10% početnih sredstava. Metrike imaju 60%, a ocene agenata 40% težine.'},
 {name:'Sales',short:'Sales',input:15,output:'Preorder',duration:'2–6 nedelja',demo:22000,desc:'Za 15 finalista pripremite stranice za poručivanje i veći budžet za marketing. Rezultat su prednarudžbine i procena povrata.',tasks:['Priprema order stranica za 15 finalista','Povećanje marketinga po finalnoj ideji','Simulacija potvrđenih prednarudžbina','Obračun prihoda, očekivanog ROI i vremena povrata'],hint:'Interesovanje postaje porudžbina.',hintText:'Broj i vrednost prednarudžbina prikazuju se po ideji. Demo potvrda je simulirana; stvarna validacija zahteva kupca i evidenciju porudžbine.'}
];
const DEFAULT_PARAMS={name:'Robotics Venture Lab',industry:'Robotika i automatizacija',capital:150000,roi:18,region:'Srbija i DACH',advantages:'10 godina iskustva u industrijskoj automatizaciji, tim od 3 inženjera i postojeća mreža proizvodnih kompanija.',linkedin:'https://linkedin.com/company/robotics-demo',website:'https://robotics-demo.example',notes:'B2B rešenja za mala i srednja proizvodna preduzeća.'};
const STORAGE='forge-businesses-v2';
const LEGACY_STORAGE='forge-business-engine-v1';
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Belgrade',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function freshMeta(){return {kind:'custom',status:'planning',startedOn:null,preparedOn:today(),earned:0,profit:0,orders:0,customers:0,monthlyRevenue:[],description:'Novi biznis u pripremi.',nextAction:'Unesite parametre i pokrenite evaluaciju.',activity:[],assets:[]};}
function freshState(){return {version:1,id:'business-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),params:{...DEFAULT_PARAMS,name:'',advantages:'',linkedin:'',website:'',notes:''},created:false,activeStep:0,phases:PHASES.map(()=>({status:'idle',started:0,elapsed:0})),savedAt:0,meta:freshMeta()};}
function validRecord(d){return d&&typeof d.id==='string'&&d.params&&typeof d.params.name==='string'&&Array.isArray(d.phases)&&d.phases.length===4&&d.phases.every(p=>['idle','running','paused','complete'].includes(p.status));}
function normalizeRecord(d){return {...d,params:{...DEFAULT_PARAMS,...d.params},meta:{...freshMeta(),...d.meta},activeStep:Math.max(0,Math.min(4,Number(d.activeStep)||0))};}
let portfolio={version:2,businesses:JSON.parse(JSON.stringify(window.DEMO_BUSINESSES||[])),activeId:null,draft:null},storageOK=true;
try {
  const saved=JSON.parse(localStorage.getItem(STORAGE));
  if(saved&&saved.version===2&&Array.isArray(saved.businesses)&&saved.businesses.every(validRecord)) portfolio={...portfolio,...saved,businesses:saved.businesses.map(normalizeRecord),draft:validRecord(saved.draft)?normalizeRecord(saved.draft):null};
  else {
    const legacy=JSON.parse(localStorage.getItem(LEGACY_STORAGE));
    if(legacy&&legacy.created&&legacy.params?.name&&legacy.params.name!=='Robotics Venture Lab'&&Array.isArray(legacy.phases)&&legacy.phases.length===4) {
      portfolio.businesses.push(normalizeRecord({...legacy,id:'previous-project',meta:{...freshMeta(),description:'Sačuvan projekat iz prethodne verzije.',status:legacy.phases.every(p=>p.status==='complete')?'validation':'planning'}}));
    }
  }
} catch(e){storageOK=false;}
let state=portfolio.businesses.find(b=>b.id===portfolio.activeId)||portfolio.draft||freshState();
let route='',agentCategory='Svi agenti',agentSearch='',showAll=false,showEliminated=false,toastTimer;
function persist(){state.savedAt=Date.now();if(!portfolio.businesses.some(b=>b.id===state.id))portfolio.draft=state;try{localStorage.setItem(STORAGE,JSON.stringify(portfolio));storageOK=true;}catch(e){storageOK=false;}}
function businessKind(industry){return industry.includes('dropshipping')?'dropshipping':industry.includes('Affiliate')?'affiliate':industry.includes('Robotika')?'robot':'custom';}
function registerBusiness(){if(!portfolio.businesses.some(b=>b.id===state.id))portfolio.businesses.push(state);portfolio.activeId=state.id;portfolio.draft=null;state.meta.kind=businessKind(state.params.industry);state.meta.description=state.params.notes||'Biznis u pripremi.';}
function selectBusiness(id){const b=portfolio.businesses.find(b=>b.id===id);if(!b)return false;state=b;portfolio.activeId=id;showAll=false;showEliminated=false;persist();return true;}
function openBusiness(id){if(selectBusiness(id))routeTo('business/'+encodeURIComponent(id));}
function newBusiness(){state=freshState();portfolio.activeId=null;portfolio.draft=state;persist();if(route==='project'&&!location.hash.includes('/'))render();else routeTo('project');}
function launchBusiness(){if(!state.phases.every(p=>p.status==='complete')){toast('Prvo završite sve četiri faze validacije.');return;}if(state.meta.startedOn)return;state.meta.startedOn=today();state.meta.status='active';state.meta.nextAction='Pratite prodaju, troškove i prve kupce.';state.meta.activity.unshift({date:today(),label:'Demo poslovanje pokrenuto',description:'Validacija je završena. Operativna zarada počinje od 0 €.'});persist();render();toast('Demo poslovanje je pokrenuto.');}
function businessHandlers(){return {openBusiness,newBusiness,openStep,results:()=>routeTo('results'),back:()=>routeTo('businesses'),launch:launchBusiness};}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function elapsed(p){return p.elapsed+(p.status==='running'?Math.max(0,Date.now()-p.started):0);}
function progress(i){return state.phases[i].status==='complete'?100:Math.min(100,Math.floor(elapsed(state.phases[i])/PHASES[i].demo*100));}
function available(step){return step===0||state.created&&(step===1||state.phases[step-2].status==='complete');}
function completedCount(){return state.phases.filter(p=>p.status==='complete').length;}
function completedIds(){return state.phases.flatMap((p,i)=>p.status==='complete'?[i+1]:[]);}
function routeTo(name){location.hash=['project','results'].includes(name)&&portfolio.activeId?name+'/'+encodeURIComponent(state.id):name;}
function openStep(step){if(!available(step)){toast(state.created?'Završite prethodnu fazu da biste nastavili.':'Prvo sačuvajte parametre i kreirajte projekat.');return;}state.activeStep=step;showAll=false;showEliminated=false;persist();if(route==='project')render();else routeTo('project');}
function sidebar(){
 const hasBusiness=portfolio.businesses.some(b=>b.id===state.id);
 const running=state.phases.findIndex(p=>p.status==='running');
 $('#stage-nav').innerHTML=hasBusiness?PHASES.map((p,i)=>`<button data-step="${i+1}" class="${state.phases[i].status==='complete'?'completed':''} ${running===i?'running':''} ${route==='project'&&state.activeStep===i+1?'selected':''}" ${available(i+1)?'':'aria-disabled="true"'}><span class="stage-dot"></span>${p.short}${available(i+1)?'':ico('lock').replace('<svg ','<svg class="lock-icon" ')}</button>`).join(''):'';
 $('.stages-caption').style.display=hasBusiness?'':'none';
 const selection=$('#selected-business');
 if(selection){selection.innerHTML=hasBusiness?`<span>IZABRANI BIZNIS</span><button id="selected-business-link">${esc(state.params.name)}${ico('arrow')}</button>`:'';selection.style.display=hasBusiness?'':'none';if($('#selected-business-link'))$('#selected-business-link').onclick=()=>openBusiness(state.id);}
 const navRoute=route==='business'?'businesses':route;
 $$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===navRoute);if(a.dataset.nav===navRoute)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $$('[data-step]',$('#stage-nav')).forEach(b=>b.onclick=()=>openStep(Number(b.dataset.step)));
}
function stepper(){return `<div class="stepper" aria-label="Napredak projekta">${['Parametri',...PHASES.map(p=>p.short)].map((title,i)=>{const done=i===0?state.created:state.phases[i-1].status==='complete';return `<div class="step ${state.activeStep===i?'active':''} ${done?'complete':''}"><button class="step-button" data-step="${i}" ${state.activeStep===i?'aria-current="step"':''} ${available(i)?'':'aria-disabled="true"'}><span class="step-circle">${done?ico('check'):String(i+1).padStart(2,'0')}</span><span><span class="step-title">${title}</span><small class="step-sub">${i===0?'Osnova projekta':i===4?'15 → prednarudžbine':`${PHASES[i-1].input} → ${PHASES[i-1].output} ideja`}</small></span></button></div>`;}).join('')}</div>`;}
function heading(eyebrow,title,description,pill){return `<div class="page-heading"><div><div class="eyebrow">${ico('spark')}${eyebrow}</div><h1>${title}</h1><p class="heading-description">${description}</p></div>${pill||''}</div>`;}
function statusPill(text,kind=''){return `<span class="status-pill ${kind}"><i></i>${text}</span>`;}
function avatars(){return `<div class="avatar-stack"><span>TE</span><span>VC</span><span>MK</span><span>+21</span></div>`;}
function robotArt(){return `<svg class="robot-art" viewBox="0 0 360 250" fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Ilustracija industrijske robotske ruke na radnoj platformi"><defs><linearGradient id="floor" x1="70" y1="170" x2="290" y2="240" gradientUnits="userSpaceOnUse"><stop stop-color="#DED9ED"/><stop offset="1" stop-color="#E9E5F3"/></linearGradient><linearGradient id="arm" x1="112" y1="77" x2="181" y2="144" gradientUnits="userSpaceOnUse"><stop stop-color="#A095CA"/><stop offset="1" stop-color="#7764AC"/></linearGradient><linearGradient id="front" x1="128" y1="121" x2="179" y2="194" gradientUnits="userSpaceOnUse"><stop stop-color="#B2A5D8"/><stop offset="1" stop-color="#9481C0"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="6"/></filter></defs><g opacity=".45" stroke="#D5CCE8" stroke-width=".7"><path d="m30 194 175-89 145 74M39 208l175-89m-149 101 175-89m-144 101 175-89m-140 101 175-89M56 180l146 75M82 167l146 75M108 154l146 75M134 141l146 75M160 128l146 75M186 115l146 75"/></g><ellipse cx="182" cy="201" rx="84" ry="17" fill="#B8ACD1" opacity=".25" filter="url(#shadow)"/><path d="m76 178 105-53 109 55-105 54-109-56Z" fill="url(#floor)" stroke="#D0C6E5"/><path d="m76 178 109 56v10L76 188v-10Z" fill="#CFC5E2"/><path d="m185 234 105-54v10l-105 54v-10Z" fill="#DDD5EB"/><path d="m118 186 43-22 46 23-43 22-46-23Z" fill="#716092"/><path d="m118 186 46 23v10l-46-23v-10Z" fill="#675584"/><path d="m164 209 43-22v10l-43 22v-10Z" fill="#8672A5"/><path d="m132 155 29-15 31 16v37l-29 15-31-16v-37Z" fill="url(#front)"/><path d="m163 171 29-15v37l-29 15v-37Z" fill="#8672B2"/><path d="m132 155 29-15 31 16-29 15-31-16Z" fill="#C7BDE1"/><path d="m140 169 13 7v15l-13-7v-15Z" fill="#7A659E"/><path d="m144 174 6 3" stroke="#D9CFEE" stroke-width="2"/><path d="m148 150-19-59 16-11 23 63-20 7Z" fill="url(#arm)"/><path d="m168 143-23-63 11 6 23 63-11-6Z" fill="#675491"/><ellipse cx="151" cy="146" rx="18" ry="21" transform="rotate(-28 151 146)" fill="#7F6CAA"/><ellipse cx="148" cy="144" rx="11" ry="14" transform="rotate(-28 148 144)" fill="#D1C6E6"/><ellipse cx="148" cy="144" rx="5" ry="7" transform="rotate(-28 148 144)" fill="#AA99CC"/><path d="m141 82 62-31 10 16-63 33-9-18Z" fill="#B2A4D2"/><path d="m150 100 63-33 8 6-63 33-8-6Z" fill="#7964A8"/><ellipse cx="145" cy="90" rx="18" ry="19" transform="rotate(-30 145 90)" fill="#8773B0"/><ellipse cx="141" cy="87" rx="12" ry="13" transform="rotate(-30 141 87)" fill="#D4CAE8"/><ellipse cx="141" cy="87" rx="5" ry="6" transform="rotate(-30 141 87)" fill="#A395C7"/><path d="m204 51 14 7 18 43-14 6-18-56Z" fill="#8E7AB7"/><path d="m218 58 8-3 18 43-8 3-18-43Z" fill="#6E5998"/><ellipse cx="211" cy="59" rx="13" ry="15" transform="rotate(-25 211 59)" fill="#8B77AF"/><ellipse cx="207" cy="57" rx="8" ry="10" transform="rotate(-25 207 57)" fill="#C5B8DF"/><path d="m222 103 14-7 9 9-14 7-9-9Z" fill="#D0C4E2"/><path d="m222 103 9 9v13l-9-5v-17Z" fill="#8C79A6"/><path d="m231 112 14-7v14l-14 6v-13Z" fill="#725D93"/><path d="m226 121-6 6 5 12 5-3-4-9 5-3m8-4 7 8-4 13-6-3 3-9-6-5" stroke="#625174" stroke-width="4" stroke-linejoin="round"/><path d="m231 146 23-12 26 13-24 12-25-13Z" fill="#C6BBDB"/><path d="m231 146 25 13v21l-25-13v-21Z" fill="#B4A7CC"/><path d="m256 159 24-12v21l-24 12v-21Z" fill="#9B8AB9"/><path d="m242 141 25 13M244 159l7 3" stroke="#E5DEF0" stroke-width="2"/><g stroke="#B0A2C9" stroke-dasharray="3 4" stroke-width="1"><path d="M251 50h48v77M108 128H70v27"/></g><circle cx="251" cy="50" r="2.5" fill="#A799C2"/><circle cx="108" cy="128" r="2.5" fill="#A799C2"/><text x="271" y="42" font-family="monospace" font-size="7" fill="#A89BBE">AXIS_06</text><text x="36" y="164" font-family="monospace" font-size="7" fill="#A89BBE">ROBOTICS</text><circle cx="299" cy="131" r="2" fill="#BCADD0"/></svg>`;}
function formField(label,name,type='text',required=false,suffix=''){const val=state.params[name];return `<label class="field"><span class="field-title">${label}${required?'<span class="required">*</span>':''}</span><div class="${suffix?'input-suffix':''}"><input name="${name}" type="${type}" value="${esc(val)}" ${required?'required':''} ${type==='number'?`min="${name==='capital'?100:1}" max="${name==='capital'?100000000:120}" step="${name==='capital'?100:1}"`:''} ${type==='url'?'placeholder="https://…"':''}>${suffix?`<span>${suffix}</span>`:''}</div></label>`;}
function setup(){return `<button class="button ghost wizard-back" id="wizard-back">← ${portfolio.activeId?'Pregled biznisa':'My business'}</button>${heading('VAŠ SLEDEĆI BIZNIS POČINJE OVDE','Od ideje do prvih porudžbina.','Postavite parametre. Vaš tim agenata preuzima sledeća četiri koraka.',statusPill(state.created?'Projekat kreiran':'Nacrt projekta'))}${stepper()}<div class="setup-layout"><section class="panel"><div class="panel-head"><span class="panel-icon">${ico('edit')}</span><div><h2>Postavite temelje projekta</h2><p>Što su ulazni podaci bolji, to su ideje relevantnije.</p></div></div><form id="project-form"><div class="form-body"><div class="form-section">01 / OSNOVNI PARAMETRI</div>${formField('Naziv projekta','name','text',true)}<div class="form-row"><label class="field"><span class="field-title">Industrija<span class="required">*</span></span><select name="industry">${[...new Set(['Robotika i automatizacija','E-commerce i dropshipping','Affiliate marketing','Industrijska proizvodnja','Logistika i skladištenje','Zdravstvena tehnologija','Druga industrija',state.params.industry])].map(x=>`<option ${state.params.industry===x?'selected':''}>${x}</option>`).join('')}</select></label>${formField('Ciljno tržište','region','text',true)}</div><div class="form-row">${formField('Početni kapital','capital','number',true,'EUR')}${formField('Željeni rok povrata','roi','number',true,'meseci')}</div><p class="hint" style="margin:-10px 0 24px">Agenti koriste kapital i rok kao ograničenja u proceni svake ideje.</p><div class="form-section section-gap">02 / PREDNOSTI OSNIVAČA</div><label class="field"><span class="field-title">Šta donosite u projekat?<span class="required">*</span></span><textarea name="advantages" required maxlength="2000" placeholder="Iskustvo, tim, kontakti, tehnologija, oprema…">${esc(state.params.advantages)}</textarea><div class="advantage-chips"><span>${ico('check')}Iskustvo i znanje</span><span>${ico('check')}Tim i kontakti</span><span>${ico('check')}Tehnologija i oprema</span></div></label><div class="form-section section-gap">03 / VAŠI KANALI I KONTEKST</div><div class="form-row social-fields">${formField('LinkedIn ili druga mreža','linkedin','url')}${formField('Postojeći sajt','website','url')}</div><label class="field" style="margin:19px 0 0"><span class="field-title">Dodatni kontekst<span class="optional">opciono</span></span><input name="notes" value="${esc(state.params.notes)}" placeholder="Kupci, ciljevi ili druga ograničenja"></label></div><div class="form-actions"><button type="button" class="button ghost" id="save-draft">${ico('save')}Sačuvaj nacrt</button><span class="save-state">${ico('lock')}Čuva se lokalno</span><button type="submit" class="button primary">${state.created?'Sačuvaj i nastavi':'Kreiraj projekat'}${ico('arrow')}</button></div></form></section><aside class="setup-aside"><div class="project-preview"><div class="preview-eyebrow">INDUSTRIJA U FOKUSU</div><h2>Velike ideje.<br>Stvaran potencijal.</h2><p>${businessKind(state.params.industry)==='robot'?'Od robotske automatizacije do novog poslovnog modela.':'Od vaše publike i prednosti do održivog poslovnog modela.'} Pronađite ideju koju tržište želi.</p>${businessKind(state.params.industry)==='robot'?robotArt():`<div class="business-concept-art">${ico(businessKind(state.params.industry)==='affiliate'?'file':'grid')}<span>${esc(state.params.industry)}</span></div>`}<div class="art-caption"><span><i></i>${esc(state.params.industry.toUpperCase())}</span><span>SEKTOR / 01</span></div></div><div class="panel funnel-panel"><h3>Manje ideja. Više dokaza.${ico('funnel')}</h3><p class="funnel-caption">Svaka faza približava vas validaciji.</p>${[[100,'Početne ideje',100],[50,'Product Market Fit',80],[30,'Go-To-Market',64],[15,'Marketing → Sales',47]].map(([count,label,width])=>`<div class="funnel-row"><div class="funnel-bar" style="width:${width}%"><strong>${count}</strong><span>ideja</span></div><span class="funnel-label">${label}</span></div>`).join('')}</div><div class="agent-summary">${avatars()}<p>24 perspektive. Nezavisne ocene.<a href="#agents">Upoznajte svoj tim agenata ↗</a></p></div></aside></div>`;}
function readForm(){const f=$('#project-form');if(!f.reportValidity())return null;const d=Object.fromEntries(new FormData(f));d.capital=Number(d.capital);d.roi=Number(d.roi);for(const key of ['name','region','advantages'])if(!d[key].trim()){toast('Popunite sva obavezna polja.');return null;}return d;}
function sameParams(a,b){return Object.keys(DEFAULT_PARAMS).every(k=>String(a[k])===String(b[k]));}
function commitForm(start){const params=readForm();if(!params)return;if(!sameParams(params,state.params)&&state.phases.some(p=>p.status!=='idle')){showDialog(`<div class="dialog-kicker">PROMENA PARAMETARA</div><h2>Ponovo pokrenuti evaluaciju?</h2><p class="dialog-text">Izmenjeni ulazi menjaju sve ideje i rezultate. Čuvanjem novih parametara resetuju se četiri demo faze ovog projekta.</p><div class="dialog-actions"><button class="button secondary" id="cancel-reset">Odustani</button><button class="button primary" id="confirm-reset">Sačuvaj i resetuj</button></div>`);$('#cancel-reset').onclick=()=>$('#detail-dialog').close();$('#confirm-reset').onclick=()=>{$('#detail-dialog').close();applyParams(params,start,true);};return;}applyParams(params,start,false);}
function applyParams(params,start,reset){state.params=params;if(reset){state.phases=freshState().phases;if(!state.meta.startedOn)state.meta.status='planning';}registerBusiness();if(start){state.created=true;state.activeStep=1;}persist();if(start&&location.hash!=='#project/'+state.id)routeTo('project');else render();toast(start?'Biznis je spreman za Product Market Fit.':storageOK?'Nacrt je sačuvan u My business.':'Čuvanje nije dostupno. Izvezite projekat pre zatvaranja.');}
const names=['Cobot paletizacija','Vision QC platforma','Robot-as-a-Service','AMR skladišna logistika','Robotsko zavarivanje','Automatsko pakovanje','Servis robotskih ćelija','Digitalni blizanac','Robot za komisioniranje','Obuka za cobot operatere','Modularni hvatači','Prediktivno održavanje','Robotsko sortiranje','Automatizacija laboratorija','Mobilna inspekcija'];
const segments=['za mala preduzeća','za prehrambeni sektor','za auto industriju','za distributivne centre','za metalnu industriju','za elektronsku industriju','za farmaceutski sektor'];
function hash(s){let n=0;for(const c of s)n=(n*31+c.charCodeAt(0))>>>0;return n;}
function ideaContext(){
 const kind=businessKind(state.params.industry);
 if(kind==='dropshipping')return {kind,names:['Organizatori radnog stola','Dodaci za kućnu kancelariju','Putni organizatori','Pametna kuhinjska oprema','Oprema za ljubimce','Dodaci za fitness','Dekoracija za dom','Ekološki dodaci','Pokloni sa personalizacijom','LED rasveta','Dodaci za mobilne telefone','Oprema za kampovanje','Praktični kućni alati','Dodaci za negu','Oprema za hobi'],segments:['za kućnu kancelariju','za mlade porodice','za ljubitelje putovanja','za male stanove','za aktivne kupce','za poklone','za kreativne korisnike'],prices:[39,59,29,69,45,55,49,35,65,79,25,89,49,35,59],icp:['Kupac za kućnu kancelariju','Online kupac','Kupac za dom','Kupac poklona'],model:'Online prodaja',problem:'Online kupci traže praktične proizvode, jasne informacije i pouzdanu isporuku. Problem testiramo kroz kvalitet ponude, cenu i iskustvo kupovine.',solution:'Test prodavnica, katalog odabranih proizvoda, partnerski dobavljači, tok poručivanja i korisnička podrška.',channels:'Instagram, pretraga, sadržaj i email. Katalog: osnovni proizvod, paket i dodatna oprema.',plan:'Founder vodi asortiman i odluke, marketing vodi oglase, partner isporučuje proizvode, podrška prati narudžbine. Demo: provera dobavljača 2 nedelje, prodavnica 3 nedelje, test kampanje 4 nedelje.'};
 if(kind==='affiliate')return {kind,names:['Vodič za kućnu kancelariju','Poređenje ergonomskih stolica','Recenzije slušalica','Vodič za pametni dom','Preporuke laptop opreme','Poređenje monitora','Vodič za putne dodatke','Recenzije foto opreme','Preporuke kuhinjske opreme','Vodič za fitness uređaje','Poređenje čitača knjiga','Preporuke gaming opreme','Recenzije kancelarijske rasvete','Vodič za opremu za hobi','Poređenje kućnih alata'],segments:['za početnike','za male budžete','za napredne korisnike','za rad od kuće','za freelancere','za male timove','za kupce u DACH'],prices:[12,18,8,15,6,20,5,24,7,10,6,16,5,9,8],icp:['Čitalac vodiča za kupovinu','Kupac koji poredi proizvode','Pretplatnik newslettera','Posetilac iz pretrage'],model:'Affiliate provizija',problem:'Kupcima je teško da izaberu proizvod među brojnim ponudama. Vrednost ideje je jasan sadržaj i pomoć u odluci.',solution:'Sadržajni sajt sa poređenjima, recenzijama i demo partnerskim preporukama. Nema aktivnog partnerskog naloga ili potvrđenih provizija.',channels:'Organska pretraga, newsletter i društvene mreže. Katalog: vodiči, poređenja i recenzije.',plan:'Founder bira nišu, urednik priprema sadržaj, marketing prati saobraćaj, analitičar proverava demo konverzije. Demo: istraživanje 2 nedelje, početni sadržaj 4 nedelje, test publike 4 nedelje.'};
 return {kind,names,segments,prices:[18500,4200,12500,28000,35000,16000,2900,6400,22000,1200,3400,4800,19000,25000,7800],icp:['Direktor operacija','Menadžer kvaliteta','Direktor proizvodnje','Rukovodilac logistike'],model:'B2B prodaja + servis',problem:'Proizvodne kompanije imaju teškoće sa ponavljajućim zadacima, raspoloživošću radnika i ujednačenim kvalitetom.',solution:'Modularno robotsko rešenje uz senzore, integraciju i obuku. Pilot ćelija sa nadzorom performansi i servisnim paketom.',channels:'Direktna B2B prodaja, LinkedIn i email. Katalog: osnovni paket, integracija i godišnji servis.',plan:'Founder je odgovoran za odluke. Tehnički tim izvodi pilot, prodaja vodi kupce, a finansije i pravni agent daju procenu. Demo: istraživanje 2 nedelje, pilot 6 nedelja, prodajni test 4 nedelje.'};
}
function allIdeas(){const seed=hash(JSON.stringify(state.params)),ctx=ideaContext();return Array.from({length:100},(_,i)=>{
 const niche=ctx.segments[Math.floor(i/15)%ctx.segments.length];const name=ctx.names[i%15]+' '+niche;
 const rating=phase=>{let total=0;for(let a=0;a<24;a++)total+=62+(hash(seed+'|'+i+'|'+phase+'|'+a)%370)/10;return Math.round(total/24*10)/10;};
 const price=ctx.prices[i%15],units=ctx.kind==='dropshipping'?100:ctx.kind==='affiliate'?120:1;
 return {id:i+1,name,score:rating(1),gtmScore:rating(2),marketingScore:Math.round((rating(3)*.4+(65+(hash('m'+seed+i)%300)/10)*.6)*10)/10,price,investment:Math.round(state.params.capital*(.5+((i+1)%6)*.06)),monthlyCash:Math.round(price*units*(ctx.kind==='dropshipping'?.25:.6+((i+1)%5)*.1)),icp:ctx.icp[i%4],visits:1800+hash('v'+seed+i)%6500,replies:20+hash('e'+seed+i)%160,subscribers:80+hash('s'+seed+i)%600};
});}
function rankedIdeas(stage,all=false){let ideas=allIdeas().sort((a,b)=>b.score-a.score||a.id-b.id);if(stage===1)return all?ideas:ideas.slice(0,50);ideas=ideas.slice(0,50).sort((a,b)=>b.gtmScore-a.gtmScore||a.id-b.id);if(stage===2)return all?ideas:ideas.slice(0,30);ideas=ideas.slice(0,30).sort((a,b)=>b.marketingScore-a.marketingScore||a.id-b.id);if(stage===3)return all?ideas:ideas.slice(0,15);return ideas.slice(0,15).map((x,i)=>({...x,preorders:Math.max(3,25-i+hash('o'+x.id)%10)}));}
function financial(x){return {revenue:x.price*(x.preorders||0),roi:Math.round((x.monthlyCash*state.params.roi/x.investment-1)*100),payback:Math.round(x.investment/x.monthlyCash*10)/10};}
function phaseView(){const i=state.activeStep-1,p=PHASES[i],job=state.phases[i];const statuses={idle:'Spremno za pokretanje',running:'Obrada u toku',paused:'Pauzirano',complete:'Faza završena'};return `${heading(`FAZA ${String(i+1).padStart(2,'0')} / ${esc(state.params.name)}`,p.name,p.desc,statusPill(statuses[job.status],job.status==='complete'?'complete':job.status==='running'?'running':''))}${stepper()}<div class="phase-banner">${ico('clock')}<span><strong>Proces može trajati ${p.duration.toLowerCase()}.</strong> Demo prikazuje ovu fazu za ${p.demo/1000} s.</span><a href="#agents">24 agenta ↗</a></div><div class="phase-layout"><section class="panel phase-card"><div class="phase-card-header"><div><div class="phase-number">${i===3?'VALIDACIJA PRODAJE':'EVALUACIJA & SELEKCIJA'}</div><h2>${i===3?'Od interesovanja do prednarudžbine':`Sledeći izbor: ${p.output} najboljih ideja`}</h2></div><span class="panel-icon">${ico(i===3?'chart':'funnel')}</span></div><div class="phase-visual"><div class="phase-metric"><strong>${p.input}</strong><small>${i===0?'generisanih ideja':'ulaznih ideja'}</small></div>${ico('arrow')}<div class="phase-metric output"><strong>${p.output}</strong><small>${i===3?'broj i prihod po ideji':'ideja za sledeću fazu'}</small></div><div class="phase-duration"><strong>${ico('clock').replace('<svg ','<svg style="display:inline;width:13px;height:13px;vertical-align:middle;margin-right:4px" ')}${p.duration}</strong><small>Okvirno trajanje stvarnog procesa</small></div></div><ul class="task-list" id="phase-tasks">${taskMarkup(i)}</ul><div id="progress-section">${progressMarkup(i)}</div><div class="phase-actions" id="phase-actions">${phaseActions(i)}</div><div class="live-log" id="live-log">${liveLog(i)}</div></section><aside><div class="panel phase-aside"><h3>Vaš projektni brief</h3><p>${esc(state.params.name)}</p><div class="agent-summary">${avatars()}<p><strong>24 stručna agenta</strong><a href="#agents">Pogledajte odgovornosti ↗</a></p></div><div class="kv"><span>Industrija</span><strong>${esc(state.params.industry)}</strong></div><div class="kv"><span>Tržište</span><strong>${esc(state.params.region)}</strong></div><div class="kv"><span>Kapital</span><strong>${money(state.params.capital)}</strong></div><div class="kv"><span>Ciljani povrat</span><strong>${state.params.roi} meseci</strong></div>${i>=2?`<div class="kv"><span>Budžet po ideji</span><strong>${money(state.params.capital*(i===2?.1/30:.2/15))}</strong></div>`:''}<p class="small-note">${i===2?'Isti budžet za svih 30 ideja.':i===3?'20% početnog kapitala za marketing: četiri puta veći budžet po ideji nego u prethodnoj fazi.':'Svaki agent ocenjuje svaku ideju iz svoje oblasti.'}</p></div><div class="insight-card">${ico('spark')}<h3>${p.hint}</h3><p>${p.hintText}</p></div></aside></div>${job.status==='complete'?resultsTable(i+1):''}<p class="small-note">Demo simulacija • Nema stvarnog rada AI agenata, slanja emailova, kampanja ili naplate. Napredak i podaci čuvaju se u ovom pregledaču.</p>`;}
function taskMarkup(i){const pct=progress(i),job=state.phases[i];return PHASES[i].tasks.map((t,k)=>{const done=pct>=(k+1)*25;const current=!done&&pct>=k*25&&(job.status==='running'||job.status==='paused');return `<li class="${done?'done':current?'current':''}">${ico(done?'check':current&&job.status==='running'?'loading':'circle')}<span>${t}</span><span class="task-state">${done?'Završeno':current?(job.status==='paused'?'Pauza':'U toku'):'Na čekanju'}</span></li>`;}).join('');}
function progressMarkup(i){const pct=progress(i),job=state.phases[i];return `<div class="progress-meta"><span>${job.status==='complete'?'Evaluacija završena':job.status==='idle'?'Demo još nije pokrenut':job.status==='paused'?'Napredak sačuvan · pauza':'Demo evaluacija u toku'}</span><strong>${pct}%</strong></div><div class="progress-track" role="progressbar" aria-label="Napredak faze" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct}%"></div></div><div class="progress-info">${job.status==='complete'?'Rezultati su spremni. Možete ih pregledati i preći u sledeću fazu.':job.status==='idle'?'Pokrenite fazu kada ste spremni. Simulacija traje manje od jednog minuta.':'Možete otvoriti stranicu agenata ili zatvoriti sajt i nastaviti kasnije. Demo vreme računa se od trenutka pokretanja.'}</div>`;}
function phaseActions(i){const job=state.phases[i];let main=job.status==='idle'?`<button class="button primary" id="run-phase">${ico('play')}Pokreni demo fazu</button>`:job.status==='running'?`<button class="button secondary" id="pause-phase">${ico('pause')}Pauziraj proces</button>`:job.status==='paused'?`<button class="button primary" id="resume-phase">${ico('play')}Nastavi proces</button>`:i<3?`<button class="button primary" data-next="${i+2}">Nastavi na ${PHASES[i+1].short}${ico('arrow')}</button>`:`<button class="button primary" id="go-results">Pogledaj sve rezultate${ico('arrow')}</button>`;return `<button class="button ghost" id="back-phase">← ${i===0?'Parametri projekta':'Prethodna faza'}</button>${main}`;}
function liveLog(i){const p=progress(i),job=state.phases[i];if(job.status==='idle')return '<strong>Spremno.</strong> Ulazni parametri su sačuvani. Svi agenti dobijaju isti brief.';if(job.status==='complete')return `<strong>24 / 24 evaluacije završene.</strong> ${i===3?'Simulirane prednarudžbine i finansijski model su spremni.':`${PHASES[i].output} ideja prolazi u sledeću fazu.`}`;return `<strong>${Math.floor(p*24/100)} / 24 evaluacije.</strong> ${job.status==='paused'?'Proces čeka nastavak.':PHASES[i].tasks[Math.min(3,Math.floor(p/25))]+'.'}`;}
function runPhase(i){const job=state.phases[i];if(!available(i+1))return;if(!['idle','paused'].includes(job.status))return;job.status='running';job.started=Date.now();persist();render();toast('Demo faza je pokrenuta.');}
function pausePhase(i){const job=state.phases[i];if(job.status!=='running')return;job.elapsed=elapsed(job);job.started=0;job.status='paused';persist();render();toast('Proces je pauziran. Napredak je sačuvan.');}
function tick(){let changed=false;
 const records=[...portfolio.businesses];if(!records.some(b=>b.id===state.id))records.push(state);
 records.forEach(b=>b.phases.forEach((job,i)=>{if(job.status==='running'&&elapsed(job)>=PHASES[i].demo){job.status='complete';job.elapsed=PHASES[i].demo;job.started=0;changed=true;if(b.id===state.id)toast(`${PHASES[i].name}: demo rezultati su spremni.`);if(b.phases.every(p=>p.status==='complete')&&!b.meta.startedOn){b.meta.status='validation';b.meta.nextAction='Validacija završena. Spremno za demo poslovanje.';}}}));
 if(changed){persist();render();}else if(route==='project'&&state.activeStep>0&&state.phases[state.activeStep-1].status==='running'){const i=state.activeStep-1;if($('#phase-tasks')){$('#phase-tasks').innerHTML=taskMarkup(i);$('#progress-section').innerHTML=progressMarkup(i);$('#live-log').innerHTML=liveLog(i);}}
}
function resultsTable(stage){const rows=rankedIdeas(stage,showEliminated),p=PHASES[stage-1];const list=showAll?rows:rows.slice(0,5);return `<section class="panel results-panel"><div class="panel-title-row"><div><h2>${stage===4?'Prednarudžbine po ideji':`Najbolje ideje · ${rows.length}`}</h2><p>${stage===4?'Simulirane potvrde kupaca, prihodi i očekivani povrat.':'Nezavisne ocene 24 agenta, objedinjene u rang listu.'}</p></div><button class="button secondary" id="export-csv">${ico('download')}Izvezi CSV</button></div><div class="table-wrap"><table><thead><tr><th>POSLOVNA IDEJA</th>${stage===1?'<th>OCENA / 100</th><th>MODEL</th>':stage===2?'<th>ICP</th><th>CENA</th><th>OCENA</th>':stage===3?'<th>POSETE</th><th>EMAIL ODGOVORI</th><th>PRETPLATE</th><th>OCENA</th>':'<th>PREORDER</th><th>PRIHOD</th><th>ROI</th><th>POVRAT</th>'}<th></th></tr></thead><tbody>${list.map((x,k)=>`<tr><td><span class="rank">${String(k+1).padStart(2,'0')}</span>${esc(x.name)}</td>${stage===1?`<td><span class="score">${number(x.score)}</span></td><td>${esc(ideaContext().model)}</td>`:stage===2?`<td>${x.icp}</td><td>${money(x.price)}</td><td><span class="score">${number(x.gtmScore)}</span></td>`:stage===3?`<td>${number(x.visits)}</td><td>${x.replies}</td><td>${x.subscribers}</td><td><span class="score">${number(x.marketingScore)}</span></td>`:`<td>${x.preorders}</td><td>${money(financial(x).revenue)}</td><td><span class="score">${financial(x).roi}%</span></td><td>${number(financial(x).payback)} mes.</td>`}<td><button class="table-action" data-idea="${x.id}" aria-label="Otvori plan: ${esc(x.name)}">${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="phase-actions" style="margin-top:17px"><button class="button ghost" id="toggle-all">${showAll?'Prikaži prvih 5':`Prikaži svih ${rows.length} ideja`} ${ico(showAll?'close':'arrow')}</button>${stage<4?`<button class="button ghost" id="toggle-eliminated">${showEliminated?`Samo odabranih ${p.output}`:`Sve ulazne ideje (${p.input})`}</button>`:'<span class="small-note" style="margin:0">Sve porudžbine su demo podaci.</span>'}</div></section>`;}
function showIdea(id,stage=visibleResultStage){const x=rankedIdeas(4).find(x=>x.id===id)||allIdeas().find(x=>x.id===id);if(!x)return;const final=stage===4&&state.phases[3].status==='complete'&&x.preorders;const model=financial(x);const finance=final?model:null;const ctx=ideaContext();showDialog(`<div class="dialog-kicker">DEMO BIZNIS PLAN · IDEJA ${String(id).padStart(3,'0')}</div><h2>${esc(x.name)}</h2><p class="dialog-text">Industrija: ${esc(state.params.industry)} · Tržište: ${esc(state.params.region)}. Predlog se oslanja na prednosti osnivača i početni kapital od ${money(state.params.capital)}.</p><div class="dialog-grid"><section><h3>Problem i tržište</h3><p>${esc(ctx.problem)} Demo ICP: ${x.icp} u ${esc(state.params.region)}.</p></section><section><h3>Rešenje i tehnologija</h3><p>${esc(ctx.solution)}</p></section><section><h3>RACI i rokovi</h3><p>${esc(ctx.plan)}</p></section><section><h3>Finansije i ROI</h3><p>Cena ponude: ${money(x.price)}. ${finance?`Model ulaganja: ${money(x.investment)}. Neto operativni priliv: ${money(x.monthlyCash)} mesečno. Očekivani ROI za ${state.params.roi} meseci: ${finance.roi}%; povrat ${number(finance.payback)} meseci.`:`Planirano ulaganje: ${money(x.investment)}. Pretpostavljeni neto priliv: ${money(x.monthlyCash)} mesečno. Očekivani ROI za ${state.params.roi} meseci: ${model.roi}%; povrat ${number(model.payback)} meseci. Ovo je procena pre tržišnog testa.`}</p></section><section><h3>${stage>=2?'GTM i katalog':'Predloženi kanali'}</h3><p>${esc(ctx.channels)} Demo dostupna publika: ${number(1000+id*87)} kompanija.</p></section><section><h3>Ocene agenata</h3><p>PMF ${number(x.score)}/100${stage>=2?' · GTM '+number(x.gtmScore)+'/100':''}${stage>=3?' · Marketing '+number(x.marketingScore)+'/100':''}. Svi agenti ocenjuju nezavisno; ove ocene su simulirane.</p></section></div>${finance?`<div class="phase-banner" style="margin-top:20px;margin-bottom:0">${ico('check')}<span>${x.preorders} demo prednarudžbina · ${money(finance.revenue)} vrednosti</span></div>`:''}<p class="small-note">Finansijski model je ilustrativan: ROI = (mesečni neto priliv × rok − ulaganje) / ulaganje. Prednarudžbine predstavljaju vrednost demo ugovorenih porudžbina, bez dokaza naplate. Nisu realizovan prihod.</p>`);}
function agentsView(){return `${heading('TIM KOJI PROVERAVA VAŠE IDEJE','24 agenta. Jedna jasnija odluka.','Svaku ideju nezavisno procenjuju stručnjaci iz različitih oblasti.',statusPill('Demo tim'))}<div class="rubric-strip"><div class="rubric-item accent"><strong>24</strong><small>stručna agenta</small></div><div class="rubric-item"><strong>4</strong><small>oblasti ekspertize</small></div><div class="rubric-item"><strong>4</strong><small>faze evaluacije</small></div><div class="rubric-item"><strong>100%</strong><small>nezavisne ocene</small></div></div><div class="agents-toolbar"><div class="filter-tabs">${['Svi agenti','Produkt','Kapital','Rast','Operacije'].map(c=>`<button class="filter-tab ${agentCategory===c?'active':''}" data-category="${c}" aria-pressed="${agentCategory===c}">${c}${c==='Svi agenti'?' · 24':''}</button>`).join('')}</div><label class="search-box">${ico('search')}<input id="agent-search" aria-label="Pretraži agente" value="${esc(agentSearch)}" placeholder="Pretraži agente…"></label></div><div class="agents-grid" id="agents-grid">${agentCards()}</div><p class="small-note">U stvarnom procesu agenti bi bili unapred pripremljeni stručnjaci. Ovaj prototip prikazuje njihove uloge i simulirane nezavisne ocene, bez povezivanja sa AI servisom.</p>`;}
function agentCards(){return (window.AGENTS||[]).filter(a=>(agentCategory==='Svi agenti'||a.category===agentCategory)&&`${a.name} ${a.role} ${a.description}`.toLocaleLowerCase().includes(agentSearch.toLocaleLowerCase())).map(a=>`<article class="agent-card"><div class="agent-card-top"><span class="agent-avatar ${esc(a.category)}">${esc(a.role.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="agent-category">${esc(a.category).toUpperCase()}</span></div><h3>${esc(a.name)}</h3><span class="agent-role">${esc(a.role)}</span><p class="agent-description">${esc(a.description)}</p><div class="agent-card-bottom"><span>Sve 4 faze · nezavisna ocena</span><button data-agent="${esc(a.id)}">Opis agenta ${ico('arrow')}</button></div></article>`).join('')||'<div class="agent-no-results">Nema agenata koji odgovaraju pretrazi.</div>';}
function bindAgents(){ $$('[data-agent]').forEach(b=>b.onclick=()=>{const a=window.AGENTS.find(a=>String(a.id)===b.dataset.agent);showDialog(`<div class="dialog-kicker">${esc(a.category)} · NEZAVISNI EVALUATOR</div><h2>${esc(a.name)}</h2><p class="dialog-text">${esc(a.description)}</p><div class="dialog-grid"><section><h3>Ulaz</h3><p>${esc(a.input)}</p></section><section><h3>Izlaz</h3><p>${esc(a.output)}</p></section></div><h3 style="margin-top:20px">Kako učestvuje u odluci</h3><p class="dialog-text">Ocenjuje svaku ideju iz svoje oblasti na skali 0–100, nezavisno od drugih agenata. U PMF i GTM fazama koristi se prosek svih 24 ocene. U Marketing fazi kombinujemo metrike (60%) i prosečnu ocenu agenata (40%). U Sales fazi dodaje procenu rizika uz prednarudžbine.</p><p class="small-note">Demo uloga i ocene. Agent trenutno ne izvršava stvarne zadatke niti koristi spoljne podatke.</p>`);});}
function resultsView(){const n=completedCount();if(n===0)return `${heading('DOKAZI I ODLUKE NA JEDNOM MESTU','Rezultati vašeg projekta','Pratite izbor ideja i njihove poslovne pokazatelje.')}<div class="empty-state">${ico('chart')}<h2>Prvi rezultati čekaju vašu ideju.</h2><p>Kreirajte projekat i završite Product Market Fit fazu. Ovde ćete dobiti rang listu ideja i kasnije demo prednarudžbine, ROI i rok povrata.</p><button class="button primary" id="return-project">Otvori projekat${ico('arrow')}</button></div>`;const stage=Math.max(...completedIds());const rows=rankedIdeas(stage),final=stage===4;const total=final?rows.reduce((n,x)=>n+x.preorders,0):0;const revenue=final?rows.reduce((n,x)=>n+financial(x).revenue,0):0;return `${heading('OD PARAMETARA DO TRŽIŠNOG SIGNALA','Rezultati vašeg projekta',esc(state.params.name)+' · Sve vrednosti su demonstracioni podaci.',statusPill(final?'Sve faze završene':`${n} / 4 faze završene`,final?'complete':''))}<div class="result-stats"><div class="stat-card"><small>Odabrane poslovne ideje</small><strong>${rows.length}</strong><p>Posle faze ${PHASES[stage-1].short}</p></div><div class="stat-card highlight"><small>Demo prednarudžbine</small><strong>${final?number(total):'—'}</strong><p>${final?'Simulirane potvrde kupaca':'Dostupno posle Sales faze'}</p></div><div class="stat-card"><small>Vrednost prednarudžbina</small><strong>${final?money(revenue):'—'}</strong><p>${final?'Zbir alternativnih demo ideja':'Dostupno posle Sales faze'}</p></div><div class="stat-card"><small>Ciljani rok povrata</small><strong>${state.params.roi} <span style="font-size:13px">mes.</span></strong><p>Vaš ulazni parametar</p></div></div><div class="panel-title-row"><div class="filter-tabs">${completedIds().map(s=>`<button class="filter-tab ${stage===s?'active':''}" data-result-stage="${s}" aria-pressed="${stage===s}">${PHASES[s-1].short}</button>`).join('')}</div><button class="button secondary" id="export-project">${ico('download')}Izvezi projekat</button></div><div id="result-table-container">${resultsTable(stage)}</div><p class="small-note">Ideje su alternativni poslovni scenariji. Zbir preorder vrednosti nije prognoza prihoda jednog biznisa. Finansijski model po ideji prikazuje sopstveno ulaganje, pretpostavljeni neto priliv i povrat. Sve potvrde su simulirane.</p>`;}
let visibleResultStage=1;
function bindTable(stage){visibleResultStage=stage;$$('[data-idea]').forEach(b=>b.onclick=()=>showIdea(Number(b.dataset.idea),stage));if($('#export-csv'))$('#export-csv').onclick=()=>exportCSV(stage);if($('#toggle-all'))$('#toggle-all').onclick=()=>{showAll=!showAll;refreshTable(stage);};if($('#toggle-eliminated'))$('#toggle-eliminated').onclick=()=>{showEliminated=!showEliminated;refreshTable(stage);};}
function refreshTable(stage){if(route==='results')$('#result-table-container').innerHTML=resultsTable(stage);else $('.results-panel').outerHTML=resultsTable(stage);bindTable(stage);}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Izvoz je pripremljen.');}
function exportCSV(stage){const rows=rankedIdeas(stage,showEliminated);const header=['ID','Ideja','PMF ocena','GTM ocena','Marketing ocena','Cena EUR','Posete','Email odgovori','Newsletter pretplate','Demo preorders','Vrednost preorder EUR','ROI procenat','Povrat meseci','Podaci'];const data=rows.map(x=>[x.id,x.name,x.score,stage>=2?x.gtmScore:'',stage>=3?x.marketingScore:'',x.price,stage>=3?x.visits:'',stage>=3?x.replies:'',stage>=3?x.subscribers:'',stage===4?x.preorders:'',stage===4?financial(x).revenue:'',financial(x).roi,financial(x).payback,'DEMO SIMULACIJA']);const safe=v=>{const s=String(v??'');return /^[=+\-@\t\r]/.test(s)?"'"+s:s;};download('\ufeff'+[header,...data].map(row=>row.map(x=>'"'+safe(x).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'business-engine-'+PHASES[stage-1].short.toLowerCase().replaceAll(' ','-')+'.csv','text/csv;charset=utf-8');}
function exportProject(){download(JSON.stringify({application:'FORGE Business Engine',dataType:'DEMO',exportedAt:new Date().toISOString(),project:state,results:completedIds().map(stage=>({phase:PHASES[stage-1].name,ideas:rankedIdeas(stage).map(x=>({...x,financialModel:financial(x)}))}))},null,2),'business-engine-project.json','application/json');}
function showDialog(html){$('#dialog-content').innerHTML=html;$('#detail-dialog').showModal();}
function help(){showDialog(`<div class="dialog-kicker">BUSINESS ENGINE / VODIČ</div><h2>Vaši biznisi, od ideje do poslovanja</h2><p class="dialog-text">Početna stranica My business prikazuje sve vaše biznise. New business pokreće zaseban wizard, a detalji čuvaju pripremu, validaciju i pregled poslovanja. Ovaj demo prati strukturu dokumenta Business Engine. Sve četiri faze mogu biti zaseban proizvod; ovde su povezane u jedan čarobnjak.</p><ol class="help-list"><li><strong>Parametri:</strong> naziv, industrija, kapital, ciljani rok povrata, prednosti osnivača i postojeći kanali.</li><li><strong>Product Market Fit:</strong> 100 ideja i biznis planovi → 50 najboljih.</li><li><strong>Go-To-Market:</strong> region, ICP, cene, katalog i kanali → 30 ideja.</li><li><strong>Marketing:</strong> jednak budžet, posete, email odgovori i pretplate → 15 ideja.</li><li><strong>Sales:</strong> order stranice i veći budžet → demo prednarudžbine, ROI i vreme povrata po ideji.</li></ol><p class="dialog-text">Procesi traju 18–24 sekunde u ovom prikazu. Možete ih pauzirati, nastaviti i pregledati rezultat. Prikazana stvarna trajanja su ilustrativna; dokument posebno predviđa više nedelja za Marketing.</p><p class="small-note">24 AI stručnjaka, kampanje, sajtovi i porudžbine ovde su simulirani. Nema povezivanja sa spoljnim servisima ili naplate. Projekat se čuva lokalno u pregledaču.</p>`);}
function render(){
 sidebar();
 $('#breadcrumb-page').textContent=route==='businesses'?'My business':route==='business'?state.params.name:route==='agents'?'Tim agenata':route==='results'?'Rezultati · '+state.params.name:state.params.name||'New business';
 const app=$('#app');
 if(route==='businesses'){app.innerHTML=window.BusinessViews.home(portfolio);window.BusinessViews.bindHome(portfolio,businessHandlers());return;}
 if(route==='business'){app.innerHTML=window.BusinessViews.detail(state);window.BusinessViews.bindDetail(state,businessHandlers());return;}
 app.innerHTML=route==='agents'?agentsView():route==='results'?resultsView():state.activeStep===0?setup():phaseView();paintIcons(app);
 $$('[data-step]',app).forEach(b=>b.onclick=()=>openStep(Number(b.dataset.step)));
 if(route==='project'){
   if(state.activeStep===0){$('#project-form').onsubmit=e=>{e.preventDefault();commitForm(true);};$('#save-draft').onclick=()=>commitForm(false);$('#wizard-back').onclick=()=>portfolio.activeId?openBusiness(state.id):routeTo('businesses');}
   else{const i=state.activeStep-1;if($('#run-phase'))$('#run-phase').onclick=()=>runPhase(i);if($('#resume-phase'))$('#resume-phase').onclick=()=>runPhase(i);if($('#pause-phase'))$('#pause-phase').onclick=()=>pausePhase(i);if($('#back-phase'))$('#back-phase').onclick=()=>openStep(i);$$('[data-next]').forEach(b=>b.onclick=()=>openStep(Number(b.dataset.next)));if($('#go-results'))$('#go-results').onclick=()=>routeTo('results');if(state.phases[i].status==='complete')bindTable(i+1);}
 }
 if(route==='agents'){$$('[data-category]').forEach(b=>b.onclick=()=>{agentCategory=b.dataset.category;$$('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#agents-grid').innerHTML=agentCards();bindAgents();});$('#agent-search').oninput=e=>{agentSearch=e.target.value;$('#agents-grid').innerHTML=agentCards();bindAgents();};bindAgents();}
 if(route==='results'){if($('#return-project'))$('#return-project').onclick=()=>routeTo('project');if(completedCount()){bindTable(Math.max(...completedIds()));$$('[data-result-stage]').forEach(b=>b.onclick=()=>{showAll=false;showEliminated=false;$$('[data-result-stage]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#result-table-container').innerHTML=resultsTable(Number(b.dataset.resultStage));bindTable(Number(b.dataset.resultStage));});$('#export-project').onclick=exportProject;}}
}
function changeRoute(){
 const parts=location.hash.slice(1).split('/');
 let desired=['businesses','business','project','agents','results'].includes(parts[0])?parts[0]:'businesses';
 if(['business','project','results'].includes(desired)&&parts[1]){let id;try{id=decodeURIComponent(parts[1]);}catch(e){}if(!id||!selectBusiness(id)){desired='businesses';toast('Biznis nije pronađen u ovom pregledaču.');}}
 if(desired==='business'&&!portfolio.activeId)desired='businesses';
 route=desired;$('#sidebar').classList.remove('open');showAll=false;showEliminated=false;render();window.scrollTo(0,0);
}

$('#help-button').onclick=help;$('.dialog-close').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');document.addEventListener('click',e=>{if(innerWidth<=740&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle'))$('#sidebar').classList.remove('open');});window.addEventListener('hashchange',changeRoute);paintIcons();changeRoute();tick();setInterval(tick,500);
